//! The entire authored Go reference model is generated by test-payday-contracts.py.
#![cfg(all(not(target_arch = "wasm32"), feature = "sqlite"))]
use base64::{Engine, engine::general_purpose::STANDARD};
use diesel::{Connection, connection::SimpleConnection};
use paydirt_store::{
    Call, Frame, Packet, Scope, Store,
    integrity::{Keys, Verdict},
};
use serde_json::{Value, json};
use std::path::Path;

struct Fixture {
    model: String,
    policies: Value,
    schema: String,
    descriptors: Vec<u8>,
}
impl Fixture {
    fn read(dir: &Path) -> Self {
        let text = |n: &str| std::fs::read_to_string(dir.join(n)).unwrap();
        Self {
            model: text("model.json"),
            policies: serde_json::from_str(&text("policies.json")).unwrap(),
            schema: text("admission.json"),
            descriptors: std::fs::read(dir.join("descriptors.binpb")).unwrap(),
        }
    }
    fn open(&self, url: &str, policy: &Value, keys: bool) -> Store {
        let db = Store::open(url, &self.model, &policy.to_string())
            .unwrap()
            .with_trail(Default::default(), &self.descriptors, &self.schema)
            .unwrap();
        if keys {
            db.with_audit_keys(Keys::new(vec![15; 32], vec![], Default::default()).unwrap())
                .unwrap()
        } else {
            db
        }
    }
}
fn backends(run: impl Fn(&Fixture, &str, &dyn Fn(&str)) + std::panic::RefUnwindSafe) {
    let Some(path) = std::env::var_os("PAYDIRT_REFERENCE_STORAGE") else {
        return;
    };
    let input = Fixture::read(Path::new(&path));
    let dir = tempfile::tempdir().unwrap();
    let file = dir.path().join("fixture.sqlite");
    let url = file.to_str().unwrap();
    run(&input, url, &|sql| {
        diesel::SqliteConnection::establish(url)
            .unwrap()
            .batch_execute(sql)
            .unwrap()
    });
    #[cfg(feature = "postgres")]
    if let Ok(url) = std::env::var("DATABASE_URL") {
        let schema = format!("reference_{}", hex::encode(paydirt::mint(0)));
        let admin = || diesel::PgConnection::establish(&url).unwrap();
        admin()
            .batch_execute(&format!("CREATE SCHEMA {schema}"))
            .unwrap();
        let scoped = format!(
            "{url}{}options=-csearch_path%3D{schema}",
            if url.contains('?') { "&" } else { "?" }
        );
        let result = std::panic::catch_unwind(|| {
            run(&input, &scoped, &|sql| {
                diesel::PgConnection::establish(&scoped)
                    .unwrap()
                    .batch_execute(sql)
                    .unwrap()
            })
        });
        admin()
            .batch_execute(&format!("DROP SCHEMA {schema} CASCADE"))
            .unwrap();
        if let Err(err) = result {
            std::panic::resume_unwind(err);
        }
    }
}
fn provision(db: &mut Store) -> [u8; 16] {
    let id = paydirt::mint(1);
    db.call(
        &Scope::Internal,
        Call {
            entity: "app.Tenant".into(),
            method: "Add".into(),
            request: json!({"id":STANDARD.encode(id),"alias":"owner"}),
        },
    )
    .unwrap();
    id
}
fn write(db: &mut Store, tenant: &[u8; 16], kind: &str, method: &str, request: Value) -> Value {
    let frame:Frame=serde_json::from_value(json!({"actor":paydirt::mint(2),"tenant":tenant,"action":format!("/{kind}Service/{method}")})).unwrap();
    db.handle(Packet::Begin {
        id: "operator".into(),
        frame,
    })
    .unwrap();
    let result = db.handle(Packet::Call {
        id: "operator".into(),
        call: Call {
            entity: kind.into(),
            method: method.into(),
            request,
        },
    });
    db.handle(Packet::Finish {
        id: "operator".into(),
        commit: result.is_ok(),
    })
    .unwrap();
    result.unwrap()
}
fn id(v: &Value) -> [u8; 16] {
    STANDARD
        .decode(v.as_str().unwrap())
        .unwrap()
        .try_into()
        .unwrap()
}

#[test]
fn original_secret_bulk_erasure_and_kind_selection() {
    backends(|fixture, url, raw| {
        let mut db = fixture.open(url, &fixture.policies, false);
        let tenant = provision(&mut db);
        let tref = json!({"id":STANDARD.encode(tenant)});
        let before = write(
            &mut db,
            &tenant,
            "app.Robot",
            "Add",
            json!({"tenant":tref,"alias":"before"}),
        );
        let mut db = fixture.open(url, &fixture.policies, true);
        assert_eq!(
            db.verify_object("app.Robot", id(&before["id"]))
                .unwrap()
                .digest,
            Verdict::NoDigest
        );
        let rows = write(
            &mut db,
            &tenant,
            "app.Robot",
            "AddMany",
            json!({"items":[{"tenant":tref,"alias":"first"},{"tenant":tref,"alias":"second"}]}),
        );
        for row in rows["items"].as_array().unwrap() {
            let result = db.verify_object("app.Robot", id(&row["id"])).unwrap();
            assert_eq!(result.digest, Verdict::Matches);
            assert_eq!(result.seal, Some(Verdict::Matches));
        }
        let robot = id(&rows["items"][0]["id"]);
        write(
            &mut db,
            &tenant,
            "app.Robot",
            "Erase",
            json!({"id":STANDARD.encode(robot)}),
        );
        assert_eq!(
            db.verify_object("app.Robot", robot).unwrap().seal,
            Some(Verdict::Matches)
        );
        raw("DELETE FROM \"pd_app__Robot\" WHERE f4='first'");
        db.transaction(&Scope::Internal, |tx| {
            tx.record_objects("app.Robot", &[robot], "/ops/Purge", true)
        })
        .unwrap();
        assert!(db.verify_object("app.Robot", robot).unwrap().seal.is_none());
        let seal = paydirt::mint(14);
        db.seed(vec![(
            "app.Seal".into(),
            json!({"id":STANDARD.encode(seal),"alias":"token","code":"original"}),
        )])
        .unwrap();
        assert_eq!(
            db.check_kind("app.Seal", None).unwrap().findings[&paydirt::format_id(&seal).unwrap()]
                .digest,
            Verdict::NotOnTrail
        );
        db.transaction(&Scope::Internal, |tx| {
            tx.record_objects("app.Seal", &[seal], "/ops/Inventory", false)
        })
        .unwrap();
        assert!(db.check_kind("app.Seal", None).unwrap().findings.is_empty());
        let model: paydirt_model::Model = serde_json::from_str(&fixture.model).unwrap();
        let column = model
            .entity("app.Seal")
            .unwrap()
            .field("code")
            .unwrap()
            .column();
        raw(&format!(
            "UPDATE \"pd_app__Seal\" SET {column}='another secret' WHERE f4='token'"
        ));
        assert_eq!(
            db.verify_object("app.Seal", seal).unwrap().digest,
            Verdict::Differs
        );
        let tally = paydirt::mint(15);
        db.seed(vec![("app.Tally".into(), json!({"id":STANDARD.encode(tally), "tenant":tref,"count":"1","token":STANDARD.encode(b"held for readback")}))]).unwrap();
        assert_eq!(
            db.check_kind("app.Tally", None).unwrap().findings
                [&paydirt::format_id(&tally).unwrap()]
                .digest,
            Verdict::NotOnTrail
        );
        assert_eq!(
            db.transaction(&Scope::Internal, |tx| tx.record_objects(
                "app.Tally",
                &[tally],
                "/test/Count",
                false
            ))
            .unwrap(),
            1
        );
        assert!(
            db.check_kind("app.Tally", None)
                .unwrap()
                .findings
                .is_empty()
        );
        let audit = db
            .call(
                &Scope::Internal,
                Call {
                    entity: "app.Audit".into(),
                    method: "List".into(),
                    request: json!({}),
                },
            )
            .unwrap();
        let line = audit["items"]
            .as_array()
            .unwrap()
            .iter()
            .find(|line| line["action"] == "/test/Count")
            .unwrap();
        assert_eq!(line["tenantId"], STANDARD.encode(tenant));
        assert!(line["digestFields"].as_array().unwrap().contains(&json!(9)));
        let pulse = paydirt::mint(16);
        db.seed(vec![(
            "app.Pulse".into(),
            json!({"id":STANDARD.encode(pulse),"process":"one","dateSeen":"2024-08-01T00:00:00Z"}),
        )])
        .unwrap();
        assert_eq!(
            db.transaction(&Scope::Internal, |tx| tx.record_objects(
                "app.Pulse",
                &[pulse],
                "/ops/Inventory",
                false
            ))
            .unwrap(),
            0
        );
        let skipped = db.check_kind("app.Pulse", None).unwrap();
        assert_eq!(skipped.checked, 0);
        assert_eq!(
            skipped.skipped.as_deref(),
            Some("a heartbeat each process writes every few seconds; a record of each is noise")
        );
        let mut prior = fixture.policies.clone();
        prior["app.Robot"]["fields"]["keeper"]["personal"] = false.into();
        let mut old = fixture.open(url, &prior, true);
        let legacy = id(&write(
            &mut old,
            &tenant,
            "app.Robot",
            "Add",
            json!({"tenant":tref,"alias":"legacy"}),
        )["id"]);
        let mut current = fixture.open(url, &fixture.policies, true);
        assert!(
            current
                .check_kind("app.Robot", None)
                .unwrap()
                .unsealed
                .contains(&paydirt::format_id(&legacy).unwrap())
        );
        current
            .transaction(&Scope::Internal, |tx| {
                tx.record_objects("app.Robot", &[legacy], "/ops/EnableSeal", false)
            })
            .unwrap();
        assert_eq!(
            current.verify_object("app.Robot", legacy).unwrap().seal,
            Some(Verdict::Matches)
        );
    })
}

#[test]
fn original_trail_scopes_seek_ties_and_walk_entire_deployment() {
    use paydirt_store::trail_page::{Cursor, Selection, Whose};
    use std::collections::BTreeSet;
    backends(|fixture, url, _| {
        let mut store = fixture.open(url, &fixture.policies, true);
        let a = paydirt::mint(1);
        let b = paydirt::mint(1);
        let nobody = [0; 16];
        let at = chrono::DateTime::parse_from_rfc3339("2020-01-01T00:00:00Z")
            .unwrap()
            .to_utc();
        let mut entries = Vec::new();
        let mut expected = Vec::new();
        let mut objects = Vec::new();
        for i in 0..1280 {
            let access = i % 2 == 1;
            let domain = if access {
                6
            } else if i % 16 == 0 {
                7
            } else {
                2
            };
            let owners = match (i / 2) % 5 {
                0 => (a, a, None),
                1 => (a, nobody, None),
                2 => (a, b, None),
                3 => (b, b, Some(a)),
                _ => (b, b, None),
            };
            let mut tenants = vec![owners.0];
            for t in [Some(owners.1), owners.2].into_iter().flatten() {
                if t != nobody && !tenants.contains(&t) {
                    tenants.push(t);
                }
            }
            let stamp = at + chrono::TimeDelta::seconds(i / 6);
            let id = paydirt::mint(if access { 6 } else { 3 });
            let mut row = json!({"id":STANDARD.encode(id),"domain":domain,"tenantId":STANDARD.encode(owners.0),
                "actorTenantId":STANDARD.encode(owners.1),"actorId":STANDARD.encode(paydirt::mint(2)),
                "dateCreated":stamp,"action":"/app.RobotService/Get"});
            if !access {
                let object = paydirt::mint(domain);
                objects.push(object);
                row["objectId"] = STANDARD.encode(object).into();
                if let Some(other) = owners.2 {
                    row["counterpartTenantId"] = STANDARD.encode(other).into();
                }
            } else if owners.2.is_some() {
                // Access has actor and filing columns and no counterparty column.
                tenants = vec![owners.0];
            }
            entries.push((if access { "app.Access" } else { "app.Audit" }.into(), row));
            expected.push((
                Cursor {
                    created: stamp,
                    key: id,
                },
                domain,
                tenants,
            ));
        }
        store.seed(entries).unwrap();
        expected.sort_by_key(|v| v.0);
        let until = at + chrono::TimeDelta::days(1);
        let read = |store: &mut Store, selection: &Selection| {
            store
                .transaction(&Scope::Internal, |tx| {
                    let mut found = Vec::new();
                    let mut cursor = None;
                    loop {
                        let page = tx.trail_page(selection, Some(until), cursor, 50)?;
                        if page.is_empty() {
                            break;
                        }
                        cursor = page.last().map(|r| r.cursor);
                        found.extend(page.into_iter().map(|r| (r.cursor, r.tenants)));
                    }
                    Ok(found)
                })
                .unwrap()
        };
        for whose in [
            Whose::Anyone,
            Whose::FiledUnder,
            Whose::Alone,
            Whose::Together,
            Whose::Sharing,
        ] {
            for domain in [None, Some(6), Some(7)] {
                for tenant in [a, b] {
                    let selection = Selection {
                        tenant,
                        whose,
                        only: domain.into_iter().collect(),
                        ..Default::default()
                    };
                    let actual = read(&mut store, &selection);
                    let want: Vec<_> = expected
                        .iter()
                        .filter(|(_, d, ts)| {
                            domain.is_none_or(|k| k == *d)
                                && match whose {
                                    Whose::Anyone => true,
                                    Whose::FiledUnder => ts[0] == tenant,
                                    Whose::Alone => ts == &[tenant],
                                    Whose::Together => ts.contains(&tenant) && ts.len() > 1,
                                    Whose::Sharing => ts[0] == tenant && ts.len() > 1,
                                    _ => unreachable!(),
                                }
                        })
                        .map(|(k, _, ts)| (*k, ts.clone()))
                        .collect();
                    assert_eq!(actual, want, "scope {whose:?}, domain {domain:?}");
                }
            }
        }
        let except = read(
            &mut store,
            &Selection {
                except: BTreeSet::from([7]),
                ..Default::default()
            },
        );
        assert_eq!(except.len(), expected.iter().filter(|v| v.1 != 7).count());
        let chosen = read(
            &mut store,
            &Selection {
                objects: BTreeSet::from([objects[3]]),
                ..Default::default()
            },
        );
        assert_eq!(chosen.len(), 1);
        store
            .transaction(&Scope::Internal, |tx| {
                let all = tx.trail_tenants(nobody, 256)?;
                let first = tx.trail_tenants(nobody, 1)?;
                assert_eq!(all, BTreeSet::from([a, b]).into_iter().collect::<Vec<_>>());
                assert_eq!(tx.trail_tenants(first[0], 256)?, all[1..]);
                Ok(())
            })
            .unwrap();
        let extra = 3 * 256 + 100;
        let padding=(0..extra).map(|i|("app.Audit".into(),json!({"id":STANDARD.encode(paydirt::mint(3)),"domain":7,
            "tenantId":STANDARD.encode(a),"actorTenantId":STANDARD.encode(a),"actorId":STANDARD.encode(nobody),
            "objectId":STANDARD.encode(paydirt::mint(7)),"action":"/test/Write","dateCreated":at+chrono::TimeDelta::seconds(i as i64/3)}))).collect();
        store.seed(padding).unwrap();
        let report = store.check_kind("app.Robot", None).unwrap();
        let expected_missing = extra + expected.iter().filter(|v| v.1 == 7).count();
        assert_eq!(
            report
                .findings
                .values()
                .filter(|f| f.digest == Verdict::Missing)
                .count(),
            expected_missing
        );
    });
}

#[test]
fn original_owed_queue_pages_and_transactional_erasure() {
    use std::collections::BTreeSet;
    backends(|fixture, url, _| {
        let instant = "2020-05-01T00:00:00Z"
            .parse::<chrono::DateTime<chrono::Utc>>()
            .unwrap();
        let mut store = fixture
            .open(url, &fixture.policies, false)
            .with_inputs(paydirt_store::Inputs::new(move || instant, paydirt::mint));
        let tenant = paydirt::mint(1);
        let ids: Vec<_> = (0..600).map(|_| paydirt::mint(10)).collect();
        for chunk in ids.chunks(120) {
            store
                .transaction(&Scope::Internal, |tx| {
                    for id in chunk {
                        tx.owe_trail_erasure(tenant, *id)?;
                    }
                    Ok(())
                })
                .unwrap();
        }
        store
            .transaction(&Scope::Internal, |tx| {
                let mut seen = BTreeSet::new();
                let mut cursor = None;
                let mut pages = 0;
                loop {
                    let rows = tx.owed_page(cursor, 50)?;
                    pages += 1;
                    if rows.is_empty() {
                        break;
                    }
                    for row in rows {
                        assert!(cursor.is_none_or(|before| row.cursor > before));
                        assert!(paydirt::has_domain(&row.cursor.key, 254));
                        assert!(seen.insert(id(&row.document["object"])));
                        cursor = Some(row.cursor);
                    }
                }
                assert_eq!(pages, 13);
                assert_eq!(seen, ids.iter().copied().collect());
                Ok(())
            })
            .unwrap();
        if url.starts_with("postgres") {
            let other = paydirt::mint(1);
            let targets = [paydirt::mint(7), paydirt::mint(2)];
            let directory = tempfile::tempdir().unwrap();
            let (queued, wait) = std::sync::mpsc::channel();
            let (entered, proceed) = std::sync::mpsc::channel();
            let mut queue = fixture.open(url, &fixture.policies, false);
            let mut maintenance = fixture.open(url, &fixture.policies, false);
            let archive =
                paydirt_store::archive_files::Archive::open(directory.path(), &[42; 32]).unwrap();
            std::thread::scope(|threads| {
                threads.spawn(move || {
                    queue
                        .transaction(&Scope::Internal, |tx| {
                            tx.owe_trail_erasure(other, targets[0])?;
                            queued.send(()).unwrap();
                            proceed.recv().unwrap();
                            tx.owe_trail_erasure(other, targets[1])
                        })
                        .unwrap()
                });
                threads.spawn(move || {
                    wait.recv().unwrap();
                    entered.send(()).unwrap();
                    let req =
                        json!({"action":"collect","tenant":paydirt::format_id(&other).unwrap()});
                    let result = maintenance
                        .manage_trail(&archive, None, serde_json::from_value(req).unwrap())
                        .unwrap();
                    assert!(result.owed.is_empty());
                });
            });
            store
                .transaction(&Scope::Internal, |tx| {
                    let rows = tx.owed_page(None, 1000)?;
                    assert_eq!(rows.len(), ids.len());
                    assert!(
                        rows.iter()
                            .all(|r| !targets.contains(&id(&r.document["object"])))
                    );
                    Ok(())
                })
                .unwrap();
        }
    });
}

#[test]
fn original_signed_manifest_rows_and_reviewed_restore() {
    use paydirt_store::{
        archive_files::Archive,
        attestation::{Acceptance, DirectoryWitness, Ed25519, Notary},
    };
    backends(|fixture, url, raw| {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path().join("vault");
        let new_archive = || {
            Archive::open(&root, &[74; 32])
                .unwrap()
                .with_notary(Notary::new(
                    Box::new(Ed25519::from_seed(&[3; 32]).unwrap()),
                    Default::default(),
                    Box::new(DirectoryWitness(dir.path().join("witness"))),
                ))
        };
        let vault = new_archive();
        let mut db = fixture.open(url, &fixture.policies, true);
        let tenant = provision(&mut db);
        let name = paydirt::format_id(&tenant).unwrap();
        let manage = |db: &mut Store, arg: Value| {
            let mut r = arg;
            r["tenant"] = json!(name);
            db.manage_trail(&vault, None, serde_json::from_value(r).unwrap())
        };
        manage(
            &mut db,
            json!({"action":"policy","policy":{"default":{"retain_ms":0}}}),
        )
        .unwrap();
        for (i, alias) in ["one", "two", "three"].iter().enumerate() {
            write(
                &mut db,
                &tenant,
                "app.Robot",
                "Add",
                json!({"tenant":{"id":STANDARD.encode(tenant)},"alias":alias}),
            );
            assert!(
                !manage(&mut db, json!({"action":"collect"}))
                    .unwrap()
                    .archived
                    .is_empty()
            );
            let point = db.attest_trail(&vault, false).unwrap().unwrap();
            assert_eq!(point.k, i as u64 + 1);
            if i == 0 {
                raw(r#"CREATE TABLE manifest_backup AS SELECT * FROM "pd_app__Archived""#);
            }
        }
        let records = db
            .transaction(&Scope::Internal, |tx| tx.archive_records())
            .unwrap();
        assert!(records.len() >= 3);
        for row in records {
            assert!(paydirt::has_domain(&row.id, 5));
            assert_eq!(row.state, paydirt_store::manifest::State::Present);
            assert_eq!(row.labels["Kind"], "robot");
            let signature = row.signature.unwrap();
            assert!(!signature.sig.is_empty() && !signature.key.is_empty());
            assert!(row.since > 0);
        }
        raw(
            r#"DELETE FROM "pd_app__Archived"; INSERT INTO "pd_app__Archived" SELECT * FROM manifest_backup"#,
        );
        assert!(db.attest_trail(&vault, false).is_err());
        assert!(db.attest_trail(&vault, true).is_err());
        let review = db.review_trail(&vault).unwrap();
        assert_eq!(
            (review.database_checkpoint, review.archive_checkpoint),
            (1, 3)
        );
        assert_eq!(review.unaccounted.len(), 2);
        let mut decision = Acceptance {
            of: review.of,
            by: "operator".into(),
            why: "restored the first database backup".into(),
            restored: 2,
        };
        assert!(db.accept_trail_restore(&vault, decision.clone()).is_err());
        decision.restored = 1;
        let accepted = db.accept_trail_restore(&vault, decision.clone()).unwrap();
        assert_eq!(accepted.k, 4);
        assert!(db.accept_trail_restore(&vault, decision).is_err());
        assert_eq!(db.attest_trail(&vault, false).unwrap().unwrap().k, 4);
        use std::io::Read;
        let mut decoded = String::new();
        flate2::read::GzDecoder::new(
            std::fs::File::open(root.join(".checkpoints/00000000000000000004.gz")).unwrap(),
        )
        .read_to_string(&mut decoded)
        .unwrap();
        let envelope: Value = serde_json::from_str(&decoded).unwrap();
        assert_eq!(envelope["checkpoint"]["accepted"]["restored"], 1);
        assert_eq!(envelope["checkpoint"]["accepted"]["by"], "operator");
        write(
            &mut db,
            &tenant,
            "app.Robot",
            "Add",
            json!({"tenant":{"id":STANDARD.encode(tenant)},"alias":"after-restore"}),
        );
        if url.starts_with("postgres") {
            let mut peer = fixture.open(url, &fixture.policies, true);
            let peer_vault = new_archive();
            std::thread::scope(|threads| {
                threads.spawn(|| {
                    peer.manage_trail(
                        &peer_vault,
                        None,
                        serde_json::from_value(json!({"action":"collect","tenant":name})).unwrap(),
                    )
                    .unwrap()
                });
                manage(&mut db, json!({"action":"collect"})).unwrap();
            });
        } else {
            manage(&mut db, json!({"action":"collect"})).unwrap();
        }
        assert_eq!(db.attest_trail(&vault, false).unwrap().unwrap().k, 5);
        raw(r#"UPDATE "pd_app__Archived" SET f7='{"Kind":"forged"}' WHERE f11='present'"#);
        assert!(db.attest_trail(&vault, false).is_err());
    });
}

#[test]
fn original_signed_transition_is_whole_or_unchanged() {
    use paydirt_store::{
        Fault,
        attestation::Signature,
        manifest::{Record, State},
    };
    backends(|fixture, url, raw| {
        let mut db = fixture.open(url, &fixture.policies, false);
        let sign =
            |_was: Option<&Record>, next: &Record| -> paydirt_store::Result<Option<Signature>> {
                Ok(Some(Signature {
                    key: STANDARD.encode(b"key"),
                    sig: STANDARD.encode(next.statement()),
                }))
            };
        let row = db
            .transaction(&Scope::Internal, |tx| {
                tx.archive_intent("ns", "example", Default::default(), sign)
            })
            .unwrap();
        let key = row.id;
        let added = db
            .transaction(&Scope::Internal, |tx| {
                tx.change_archive_record(
                    key,
                    State::Adding,
                    |r| {
                        r.digest = "sha256:abc".into();
                        r.labels.insert("a".into(), "2".into());
                        r.state = State::Present;
                        Ok(())
                    },
                    |was, next| {
                        assert_eq!(was.unwrap().signature, row.signature);
                        sign(was, next)
                    },
                )
            })
            .unwrap()
            .unwrap();
        let get = |db: &mut Store| {
            db.transaction(&Scope::Internal, |tx| tx.archive_record(key))
                .unwrap()
        };
        let stored = get(&mut db);
        assert_eq!(stored.signature, added.signature);
        assert_eq!(stored.labels["a"], "2");
        assert!(
            db.transaction(&Scope::Internal, |tx| tx.change_archive_record(
                key,
                State::Adding,
                |_| panic!("incorrect prior state"),
                sign
            ))
            .unwrap()
            .is_none()
        );
        assert!(
            db.transaction(&Scope::Internal, |tx| tx.change_archive_record(
                key,
                State::Present,
                |r| {
                    r.state = State::Erasing;
                    Ok(())
                },
                |_, _| Err(Fault::precondition("signer refused"))
            ))
            .is_err()
        );
        assert_eq!(get(&mut db).state, State::Present);
        db.transaction(&Scope::Internal, |tx| {
            tx.change_archive_record(
                key,
                State::Present,
                |r| {
                    r.state = State::Erasing;
                    Ok(())
                },
                sign,
            )
        })
        .unwrap()
        .unwrap();
        if url.starts_with("postgres") {
            let result=db.transaction(&Scope::Internal,|tx|tx.change_archive_record(key,State::Erasing,|r|{r.state=State::Present;Ok(())},|was,next|{
                raw(&format!("UPDATE \"pd_app__Archived\" SET f11='erased' WHERE f1=decode('{}','hex')",hex::encode(key)));
                sign(was,next)
            })).unwrap();
            assert!(result.is_none());
            assert_eq!(get(&mut db).state, State::Erased);
        }
    });
}

#[test]
fn original_manifest_and_access_rows_use_the_app_declared_domains() {
    use paydirt_store::{access::Observation, archive_files::Archive, audit_content::Options};
    backends(|fixture, url, _| {
        let mut policies = fixture.policies.clone();
        policies["app.Access"]["entity"]["domain"] = json!(106);
        policies["app.Archived"]["entity"]["domain"] = json!(105);
        let mut db = fixture
            .open(url, &policies, false)
            .with_trail(
                Options {
                    access: true,
                    reads: true,
                    ..Default::default()
                },
                &fixture.descriptors,
                &fixture.schema,
            )
            .unwrap();
        let tenant = provision(&mut db);
        let holder = paydirt::mint(2);
        db.handle(Packet::Observe(Observation{
            frame:serde_json::from_value(json!({"actor":holder,"tenant":tenant,"action":"/app.HolderService/List"})).unwrap(),
            request:json!({}),input:"app.HolderListRequest".into(),output:"app.HolderListResponse".into(),
            answer:Some(json!({"items":[{"id":STANDARD.encode(holder),"alias":"person","tenant":{"id":STANDARD.encode(tenant)}}]})),result:"ok".into(),reason:None,written:Default::default(),
        })).unwrap();
        let sel = paydirt_store::trail_page::Selection {
            only: [106].into(),
            ..Default::default()
        };
        let access = db
            .transaction(&Scope::Internal, |tx| tx.trail_page(&sel, None, None, 10))
            .unwrap();
        assert_eq!(access.len(), 1);
        assert!(paydirt::has_domain(&access[0].cursor.key, 106));
        assert_eq!(access[0].document["domain"], 106);
        let root = tempfile::tempdir().unwrap();
        let vault = Archive::open(root.path().join("archive"), &[14; 32]).unwrap();
        let recipient = Archive::open(root.path().join("export"), &[83; 32]).unwrap();
        let mut manage = |mut req: Value| {
            req["tenant"] = json!(paydirt::format_id(&tenant).unwrap());
            db.manage_trail(
                &vault,
                Some(&recipient),
                serde_json::from_value(req).unwrap(),
            )
            .unwrap()
        };
        manage(json!({"action":"policy","policy":{"by":{"access":{"retain_ms":0}}}}));
        assert_eq!(manage(json!({"action":"collect"})).archived.len(), 1);
        let bundle = manage(
            json!({"action":"export","operator":"reader","recipient":"holder","reason":"review"}),
        )
        .bundle
        .unwrap();
        let doc: Value = serde_json::from_slice(&recipient.read(&bundle).unwrap()).unwrap();
        assert_eq!(doc["rows"][0]["id"], STANDARD.encode(access[0].cursor.key));
        let manifest = db
            .transaction(&Scope::Internal, |tx| tx.archive_records())
            .unwrap();
        assert_eq!(manifest.len(), 1);
        assert!(paydirt::has_domain(&manifest[0].id, 105));
        assert_eq!(manifest[0].labels["Kind"], "access");
    });
}

#[test]
fn original_master_seals_rows_and_departure_destroys_only_that_tenants_key() {
    use age::x25519;
    use paydirt_store::{
        archive_files::Archive,
        audit_content::{Content, Options},
        tenant_keys::TenantKeys,
    };
    use std::collections::BTreeSet;
    backends(|fixture, url, _| {
        let dir = tempfile::tempdir().unwrap();
        let master = x25519::Identity::generate();
        let stranger = x25519::Identity::generate();
        let path = dir.path().join("archive");
        let keys = dir.path().join("keys");
        let make = |ids| {
            Archive::open(&path, &[81; 32])
                .unwrap()
                .with_tenant_keys(TenantKeys::new(&keys, vec![master.to_public()], ids).unwrap())
                .unwrap()
        };
        let writer = make(vec![]);
        let reader = make(vec![master.clone()]);
        let wrong = make(vec![stranger]);
        let mut db = fixture
            .open(url, &fixture.policies, false)
            .with_trail(
                Options {
                    default: Content::Value,
                    ..Default::default()
                },
                &fixture.descriptors,
                &fixture.schema,
            )
            .unwrap();
        let left = provision(&mut db);
        let right = paydirt::mint(1);
        db.seed(vec![(
            "app.Tenant".into(),
            json!({"id":STANDARD.encode(right),"alias":"other"}),
        )])
        .unwrap();
        let manage = |db: &mut Store, owner: &[u8; 16], mut arg: Value| {
            arg["tenant"] = json!(paydirt::format_id(owner).unwrap());
            db.manage_trail(&writer, None, serde_json::from_value(arg).unwrap())
        };
        for (owner, alias) in [(left, "private-left"), (right, "private-right")] {
            write(
                &mut db,
                &owner,
                "app.Robot",
                "Add",
                json!({"tenant":{"id":STANDARD.encode(owner)},"alias":alias,"keeper":alias}),
            );
            manage(
                &mut db,
                &owner,
                json!({"action":"policy","policy":{"by":{"robot":{"retain_ms":0}}}}),
            )
            .unwrap();
        }
        let before = db.read_tenant_trail(&reader, left).unwrap();
        assert_eq!(before.len(), 1);
        assert!(!before[0]["value"].as_str().unwrap().is_empty());
        for owner in [left, right] {
            assert_eq!(
                manage(&mut db, &owner, json!({"action":"collect"}))
                    .unwrap()
                    .archived
                    .len(),
                1
            );
        }
        let opened = db.read_tenant_trail(&reader, left).unwrap();
        assert_eq!(before, opened);
        assert!(
            db.read_tenant_trail(&writer, left)
                .unwrap_err()
                .message
                .contains("sealed")
        );
        assert!(db.read_tenant_trail(&wrong, left).is_err());
        let captured = db
            .transaction(&Scope::Internal, |tx| {
                let entries = tx.archive_records()?;
                let row = entries
                    .iter()
                    .find(|e| e.namespace == paydirt::format_id(&left).unwrap())
                    .unwrap();
                let wire = writer.read(row.digest.strip_prefix("sha256:").unwrap())?;
                Ok(serde_json::from_slice::<Value>(&wire).unwrap())
            })
            .unwrap();
        assert!(captured.get("value").is_none() && captured.get("patch").is_none());
        assert!(
            STANDARD
                .decode(captured["sealed"].as_str().unwrap())
                .unwrap()
                .starts_with(b"age-encryption.org/v1")
        );
        let tenant = paydirt::format_id(&left).unwrap();
        let owners = BTreeSet::from([tenant.clone()]);
        let master_reader =
            || TenantKeys::new(&keys, vec![master.to_public()], vec![master.clone()]).unwrap();
        assert_eq!(
            master_reader().open_row(captured.clone(), &owners).unwrap(),
            before[0]
        );
        manage(
            &mut db,
            &left,
            json!({"action":"policy","policy":{"held":["*"]}}),
        )
        .unwrap();
        assert!(manage(&mut db, &left, json!({"action":"purge"})).is_err());
        assert!(master_reader().open_row(captured.clone(), &owners).is_ok());
        manage(
            &mut db,
            &left,
            json!({"action":"policy","policy":{"by":{"robot":{"retain_ms":0}}}}),
        )
        .unwrap();
        let preview = manage(&mut db, &left, json!({"action":"purge","dry_run":true})).unwrap();
        assert_eq!(preview.keys, 1);
        assert!(keys.join(&tenant).join("recipient.json").exists());
        assert_eq!(
            manage(&mut db, &left, json!({"action":"purge"}))
                .unwrap()
                .keys,
            1
        );
        assert!(
            master_reader()
                .open_row(captured.clone(), &owners)
                .unwrap_err()
                .message
                .contains("gone")
        );
        assert!(db.read_tenant_trail(&reader, left).unwrap().is_empty());
        assert_eq!(db.read_tenant_trail(&reader, right).unwrap().len(), 1);
        write(
            &mut db,
            &left,
            "app.Robot",
            "Add",
            json!({"tenant":{"id":STANDARD.encode(left)},"alias":"later"}),
        );
        manage(&mut db, &left, json!({"action":"collect"})).unwrap();
        assert_eq!(db.read_tenant_trail(&reader, left).unwrap().len(), 1);
        assert!(master_reader().open_row(captured, &owners).is_err());
    });
}

fn trail_sample(
    tenant: [u8; 16],
    actor: [u8; 16],
    counterpart: Option<[u8; 16]>,
    object: [u8; 16],
    domain: u8,
    stamp: &str,
    action: &str,
) -> (String, Value) {
    let mut row = json!({"id":STANDARD.encode(paydirt::mint(3)),"tenantId":STANDARD.encode(tenant),"actorTenantId":STANDARD.encode(actor),"actorId":STANDARD.encode(paydirt::mint(2)),"objectId":STANDARD.encode(object),"domain":domain,"dateCreated":stamp,"action":action,"value":STANDARD.encode(b"private value"),"patch":STANDARD.encode(b"private patch")});
    if let Some(owner) = counterpart {
        row["counterpartTenantId"] = json!(STANDARD.encode(owner));
    }
    ("app.Audit".into(), row)
}

#[test]
fn deployment_and_kind_windows_receipts_and_cutoffs() {
    use paydirt_store::{
        archive_files::Archive,
        attestation::{DirectoryWitness, Ed25519, Notary},
    };
    backends(|fixture, url, _| {
        let mut db = fixture.open(url, &fixture.policies, false);
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path().join("archive");
        let vault = Archive::open(&root, &[29; 32])
            .unwrap()
            .with_notary(Notary::new(
                Box::new(Ed25519::from_seed(&[7; 32]).unwrap()),
                Default::default(),
                Box::new(DirectoryWitness(dir.path().join("witness"))),
            ));
        let a = paydirt::mint(1);
        let b = paydirt::mint(1);
        let c = paydirt::mint(1);
        let uuid = |v: [u8; 16]| paydirt::format_id(&v).unwrap();
        let name = |v: &Value| uuid(id(&v["id"]));
        let older = "2020-01-01T00:00:00Z";
        let newer = "2022-01-01T00:00:00Z";
        let sample =
            |t, domain, at| trail_sample(t, t, None, paydirt::mint(domain), domain, at, "Add");
        let ar = sample(a, 7, older);
        let ah = sample(a, 2, older);
        let br = sample(b, 7, older);
        let bh = sample(b, 2, older);
        let cr = sample(c, 7, older);
        let late = sample(c, 7, newer);
        let ch = sample(c, 2, older);
        db.seed(vec![
            ar.clone(),
            ah.clone(),
            br.clone(),
            bh.clone(),
            cr.clone(),
            late.clone(),
            ch.clone(),
        ])
        .unwrap();
        let manage = |db: &mut Store, tenant: &str, mut v: Value| {
            v["tenant"] = json!(tenant);
            db.manage_trail(&vault, None, serde_json::from_value(v).unwrap())
        };
        manage(&mut db,"deployment",json!({"action":"policy","policy":{"default":{"retain_ms":0,"discard":true},"by":{"robot":{}}}})).unwrap();
        manage(
            &mut db,
            &uuid(b),
            json!({"action":"policy","policy":{"default":{"retain_ms":0,"destroy_ms":0}}}),
        )
        .unwrap();
        manage(
            &mut db,
            &uuid(c),
            json!({"action":"policy","policy":{"default":{"retain_ms":0}}}),
        )
        .unwrap();
        let dry = db.sweep_trail(&vault, true).unwrap();
        assert_eq!(dry[&uuid(a)].removed, vec![name(&ah.1)]);
        assert_eq!(dry[&uuid(b)].removed.len(), 2);
        assert_eq!(dry[&uuid(c)].archived.len(), 3);
        assert!(vault.trail_receipts().unwrap().is_empty());
        assert!(!root.exists());
        let real = db.sweep_trail(&vault, false).unwrap();
        assert_eq!(real[&uuid(a)].removed, dry[&uuid(a)].removed);
        assert_eq!(real[&uuid(b)].removed, dry[&uuid(b)].removed);
        assert_eq!(real[&uuid(c)].archived, dry[&uuid(c)].archived);
        assert_eq!(db.read_tenant_trail(&vault, a).unwrap().len(), 1);
        assert_eq!(
            db.read_tenant_trail(&vault, a).unwrap()[0]["id"],
            ar.1["id"]
        );
        assert!(db.read_tenant_trail(&vault, b).unwrap().is_empty());
        assert!(
            db.read_tenant_trail(&vault, c)
                .unwrap()
                .iter()
                .all(|r| r["action"] == "Add")
        );
        let receipt_dir = root.join(".maintenance-receipts");
        let receipts = vault.trail_receipts().unwrap();
        assert_eq!(
            receipts
                .iter()
                .filter(|r| r.act == "destroy" && r.tenant == uuid(b) && r.place == "archive")
                .map(|r| r.rows)
                .sum::<usize>(),
            2
        );
        assert_eq!(
            receipts
                .iter()
                .filter(|r| r.act == "discard" && r.tenant == uuid(a) && r.place == "database")
                .count(),
            1
        );
        let purge = json!({"action":"purge_kind","kind":"robot","before":newer});
        let mut preview = purge.clone();
        preview["dry_run"] = json!(true);
        assert_eq!(
            manage(&mut db, &uuid(c), preview).unwrap().removed,
            [name(&cr.1)]
        );
        // Fail publication after SQL commits. A new process must publish the receipt exactly once.
        let saved = dir.path().join("saved");
        std::fs::rename(&receipt_dir, &saved).unwrap();
        std::fs::write(&receipt_dir, b"unavailable").unwrap();
        assert!(manage(&mut db, &uuid(c), purge.clone()).is_err());
        std::fs::remove_file(&receipt_dir).unwrap();
        std::fs::rename(saved, &receipt_dir).unwrap();
        let mut db = fixture.open(url, &fixture.policies, false);
        assert!(manage(&mut db, &uuid(c), purge).unwrap().removed.is_empty());
        let remain = db.read_tenant_trail(&vault, c).unwrap();
        assert_eq!(remain.len(), 2);
        assert!(remain.iter().any(|r| r["id"] == ch.1["id"]));
        assert!(remain.iter().any(|r| r["id"] == late.1["id"]));
        let rs = vault.trail_receipts().unwrap();
        let purges: Vec<_> = rs.iter().filter(|r| r.act == "purge").collect();
        assert_eq!(purges.len(), 1);
        let r = purges[0];
        assert_eq!(
            (&r.tenant, r.rows, r.place.as_str(), r.kind.as_str()),
            (&uuid(c), 1, "archive", "app.Robot")
        );
        let file = receipt_dir.join(format!("{}.json", r.id));
        let mut altered: Value = serde_json::from_slice(&std::fs::read(&file).unwrap()).unwrap();
        altered["receipt"]["rows"] = json!(200);
        std::fs::write(file, serde_json::to_vec(&altered).unwrap()).unwrap();
        assert!(vault.trail_receipts().is_err());
    });
}

#[test]
fn transactional_subject_erasure_and_tenant_departure() {
    use paydirt_store::archive_files::Archive;
    backends(|fixture, url, _| {
        let mut db = fixture.open(url, &fixture.policies, false);
        let dir = tempfile::tempdir().unwrap();
        let vault = Archive::open(dir.path(), &[31; 32]).unwrap();
        let a = paydirt::mint(1);
        let b = paydirt::mint(1);
        let who = paydirt::mint(7);
        let other = paydirt::mint(7);
        let at = "2020-01-01T00:00:00Z";
        let make = |owner, actor, counter, object, action| {
            trail_sample(owner, actor, counter, object, 7, at, action)
        };
        let added = make(a, a, None, who, "Add");
        let patched = make(a, a, None, who, "Patch");
        let neighbor = make(a, a, None, other, "Add");
        let system = make(a, [0; 16], None, other, "Add");
        let shared = make(a, b, None, other, "Move");
        let theirs = make(b, b, Some(a), other, "Move");
        let uuid = |v: [u8; 16]| paydirt::format_id(&v).unwrap();
        let manage = |db: &mut Store, owner, mut r: Value| {
            r["tenant"] = json!(uuid(owner));
            db.manage_trail(&vault, None, serde_json::from_value(r).unwrap())
        };
        db.seed(vec![added.clone()]).unwrap();
        manage(
            &mut db,
            a,
            json!({"action":"policy","policy":{"default":{"retain_ms":0}}}),
        )
        .unwrap();
        assert_eq!(
            manage(&mut db, a, json!({"action":"collect"}))
                .unwrap()
                .archived
                .len(),
            1
        );
        manage(&mut db, a, json!({"action":"policy","policy":{}})).unwrap();
        db.seed(vec![
            patched.clone(),
            neighbor.clone(),
            system.clone(),
            shared.clone(),
            theirs.clone(),
        ])
        .unwrap();
        let inspect = |db: &mut Store, sample: &Value| {
            db.read_tenant_trail(&vault, a)
                .unwrap()
                .into_iter()
                .find(|r| r["id"] == sample["id"])
                .unwrap()
        };
        let original = inspect(&mut db, &patched.1);
        let rolled = db.transaction(&Scope::Internal, |tx| {
            let plan = tx.forget_trail_in(a, &[who, who])?;
            assert_eq!(plan.blanked, [uuid(id(&patched.1["id"]))]);
            assert_eq!(plan.owed, [uuid(who)]);
            Err::<(), _>(paydirt_store::Fault::invalid("rollback"))
        });
        assert!(rolled.is_err());
        assert_eq!(inspect(&mut db, &patched.1), original);
        assert!(
            manage(&mut db, a, json!({"action":"inspect"}))
                .unwrap()
                .owed
                .is_empty()
        );
        db.transaction(&Scope::Internal, |tx| tx.forget_trail_in(a, &[who]))
            .unwrap();
        let online = inspect(&mut db, &patched.1);
        assert_eq!(
            (online["value"].as_str(), online["patch"].as_str()),
            (Some(""), Some(""))
        );
        for k in ["id", "actorId", "action", "objectId", "dateCreated"] {
            assert_eq!(online[k], original[k]);
        }
        assert_eq!(inspect(&mut db, &added.1)["value"], added.1["value"]);
        assert_eq!(
            manage(&mut db, a, json!({"action":"inspect"}))
                .unwrap()
                .owed,
            [uuid(who)]
        );
        let mut db = fixture.open(url, &fixture.policies, false);
        assert_eq!(
            manage(&mut db, a, json!({"action":"retry"}))
                .unwrap()
                .blanked,
            [uuid(id(&added.1["id"]))]
        );
        assert_eq!(inspect(&mut db, &added.1)["value"], "");
        assert_eq!(inspect(&mut db, &neighbor.1)["value"], neighbor.1["value"]);
        manage(
            &mut db,
            a,
            json!({"action":"policy","policy":{"held":["*"]}}),
        )
        .unwrap();
        assert!(manage(&mut db, a, json!({"action":"purge"})).is_err());
        manage(&mut db, a, json!({"action":"policy","policy":{}})).unwrap();
        let dry = manage(&mut db, a, json!({"action":"purge","dry_run":true})).unwrap();
        let real = manage(&mut db, a, json!({"action":"purge"})).unwrap();
        assert_eq!(real.removed, dry.removed);
        assert_eq!(real.blanked, dry.blanked);
        assert_eq!(real.removed.len(), 4);
        assert_eq!(real.blanked, [uuid(id(&shared.1["id"]))]);
        assert_eq!(inspect(&mut db, &shared.1)["value"], "");
        assert_eq!(inspect(&mut db, &theirs.1)["value"], theirs.1["value"]);
    });
}

fn count_sql(url: &str, sql: &str) -> i64 {
    use diesel::{QueryableByName, RunQueryDsl};
    #[derive(QueryableByName)]
    struct Count {
        #[diesel(sql_type=diesel::sql_types::BigInt)]
        n: i64,
    }
    #[cfg(feature = "postgres")]
    if url.starts_with("postgres") {
        return diesel::sql_query(sql)
            .get_result::<Count>(&mut diesel::PgConnection::establish(url).unwrap())
            .unwrap()
            .n;
    }
    diesel::sql_query(sql)
        .get_result::<Count>(&mut diesel::SqliteConnection::establish(url).unwrap())
        .unwrap()
        .n
}
fn table_rows(db: &mut Store, kind: &str) -> Vec<Value> {
    db.call(
        &Scope::Internal,
        Call {
            entity: kind.into(),
            method: "List".into(),
            request: json!({"size":200}),
        },
    )
    .unwrap()["items"]
        .as_array()
        .unwrap()
        .clone()
}
fn message_json(f: &Fixture, name: &str, encoded: &Value) -> Value {
    if encoded.as_str().is_none_or(str::is_empty) {
        return json!({});
    }
    let pool = buffa_reflect::DescriptorPool::decode(&*f.descriptors).unwrap();
    let bytes = STANDARD.decode(encoded.as_str().unwrap()).unwrap();
    serde_json::to_value(
        buffa_reflect::DynamicMessage::decode(pool.get_message_by_name(name).unwrap(), &*bytes)
            .unwrap(),
    )
    .unwrap()
}
fn access_store(f: &Fixture, url: &str) -> Store {
    f.open(url, &f.policies, false)
        .with_trail(
            serde_json::from_value(
                json!({"default":" VALUE ","access":true,"by":{"robot":"value"}}),
            )
            .unwrap(),
            &f.descriptors,
            &f.schema,
        )
        .unwrap()
}

#[test]
fn personal_results_queue_tenant_groups_and_unpack_only_payday_envelopes() {
    use paydirt_store::{access::Observation, archive_files::Archive};
    backends(|f, url, raw| {
        let mut db = access_store(f, url);
        let a = provision(&mut db);
        let b = paydirt::mint(1);
        let actor = paydirt::mint(2);
        let alice = paydirt::mint(2);
        let bob = paydirt::mint(2);
        let frame:Frame=serde_json::from_value(json!({"tenant":a,"actor":actor,"trace":vec![5;16],"action":"/app.HolderService/List","address":"127.0.0.1"})).unwrap();
        let person = |id: [u8; 16], t: [u8; 16]| json!({"id":STANDARD.encode(id),"tenant":{"id":STANDARD.encode(t)},"alias":"alice"});
        let make = |ty: &str, answer: Value| Observation {
            frame: frame.clone(),
            input: "app.HolderListRequest".into(),
            output: ty.into(),
            answer: Some(answer),
            request: json!({"size":10,"undeclared":"omit this"}),
            result: "ok".into(),
            reason: None,
            written: Default::default(),
        };
        let answer = json!({"items":[person(alice,a),person(alice,a),person(bob,b)]});
        assert_eq!(
            db.handle(Packet::BufferObservation(make(
                "app.HolderListResponse",
                answer
            )))
            .unwrap(),
            2
        );
        assert!(table_rows(&mut db, "app.Access").is_empty());
        raw(r#"ALTER TABLE "pd_app__Access" RENAME TO invisible_access"#);
        assert!(db.flush_access().is_err());
        raw(r#"ALTER TABLE invisible_access RENAME TO "pd_app__Access""#);
        assert_eq!(db.flush_access().unwrap(), 2);
        assert_eq!(db.flush_access().unwrap(), 0);
        let rows = table_rows(&mut db, "app.Access");
        assert_eq!(rows.len(), 2);
        for row in &rows {
            let expected = if id(&row["tenantId"]) == a {
                alice
            } else {
                bob
            };
            assert_eq!(row["subjects"], json!([STANDARD.encode(expected)]));
            assert_eq!(row["subjectCount"], 1);
            assert_eq!(row["actorTenantId"], STANDARD.encode(a));
            assert_eq!(row["actorId"], STANDARD.encode(actor));
            assert_eq!(row["traceId"], STANDARD.encode([5; 16]));
            assert_eq!(row["action"], frame.action);
            assert_eq!(row["domain"], 6);
            let detail = message_json(f, "payday.AccessDetail", &row["value"]);
            assert_eq!(detail["address"], "127.0.0.1");
            assert_eq!(
                message_json(f, "app.HolderListRequest", &detail["request"]),
                json!({"size":10})
            );
        }
        let robot = paydirt::mint(7);
        let mut machine = json!({"id":STANDARD.encode(robot),"tenant":{"id":STANDARD.encode(a)},"alias":"public"});
        assert_eq!(
            db.handle(Packet::BufferObservation(make(
                "app.Robot",
                machine.clone()
            )))
            .unwrap(),
            0
        );
        machine["keeper"] = json!("someone");
        assert_eq!(
            db.handle(Packet::BufferObservation(make("app.Robot", machine)))
                .unwrap(),
            1
        );
        db.flush_access().unwrap();
        let mut held = person(alice, a);
        held["@type"] = json!("type.googleapis.com/app.Holder");
        for field in ["value", "previous"] {
            assert_eq!(
                db.handle(Packet::BufferObservation(make(
                    "payday.WatchEvent",
                    json!({field:held})
                )))
                .unwrap(),
                1
            );
            db.flush_access().unwrap();
        }
        for (ty, answer) in [
            ("google.protobuf.Any", held.clone()),
            (
                "payday.WatchEvent",
                json!({"value":{"@type":"type.googleapis.com/google.protobuf.Any","value":held}}),
            ),
            (
                "payday.WatchEvent",
                json!({"value":{"@type":"type.googleapis.com/payday.WatchEvent","previous":held}}),
            ),
        ] {
            assert_eq!(
                db.handle(Packet::BufferObservation(make(ty, answer)))
                    .unwrap(),
                0
            );
        }
        let mut large = make("app.Holder", person(alice, a));
        large.input = "app.HolderAddRequest".into();
        large.request = json!({"alias":"x".repeat(10000)});
        large.reason = Some("case 5".into());
        db.handle(Packet::BufferObservation(large)).unwrap();
        let rs = table_rows(&mut db, "app.Access");
        let details = message_json(
            f,
            "payday.AccessDetail",
            &rs.iter().find(|r| r["kind"] == "download").unwrap()["value"],
        );
        assert_eq!(details["reason"], "case 5");
        assert!(details["request"].is_null());
        let vault_dir = tempfile::tempdir().unwrap();
        let vault = Archive::open(vault_dir.path(), &[9; 32]).unwrap();
        let manage = |db: &mut Store, mut req: Value| {
            req["tenant"] = json!(paydirt::format_id(&a).unwrap());
            db.manage_trail(&vault, None, serde_json::from_value(req).unwrap())
                .unwrap()
        };
        // A regular write supplies both an audit record and a personal Access record.
        write(
            &mut db,
            &a,
            "app.Robot",
            "Add",
            json!({"tenant":{"id":STANDARD.encode(a)},"alias":"row","keeper":"owner"}),
        );
        let audit = table_rows(&mut db, "app.Audit");
        assert!(!audit.is_empty());
        let owned = table_rows(&mut db, "app.Access")
            .into_iter()
            .filter(|r| id(&r["tenantId"]) == a)
            .count();
        manage(
            &mut db,
            json!({"action":"policy","policy":{"by":{"access":{"retain_ms":0}}}}),
        );
        assert_eq!(
            manage(&mut db, json!({"action":"collect"})).archived.len(),
            owned
        );
        assert_eq!(table_rows(&mut db, "app.Audit").len(), audit.len());
        assert!(
            table_rows(&mut db, "app.Access")
                .iter()
                .all(|r| id(&r["tenantId"]) == b)
        );
        assert_eq!(
            db.read_tenant_trail(&vault, a)
                .unwrap()
                .iter()
                .filter(|r| r.get("kind").is_some() && id(&r["tenantId"]) == a)
                .count(),
            owned
        );
    });
}

#[test]
fn personal_writes_settle_once_with_the_commit_and_local_operator() {
    use paydirt_store::access::Observation;
    backends(|f, url, raw| {
        let mut db = access_store(f, url);
        let t = provision(&mut db);
        let actor = paydirt::mint(2);
        let other = paydirt::mint(2);
        let frame:Frame=serde_json::from_value(json!({"tenant":t,"actor":actor,"action":"/custom.Writes/Rename","address":"127.0.0.1"})).unwrap();
        let add = |alias: &str| Call {
            entity: "app.Holder".into(),
            method: "Add".into(),
            request: json!({"tenant":{"id":STANDARD.encode(t)},"alias":alias}),
        };
        let start = |db: &mut Store| {
            db.handle(Packet::Begin {
                id: "call".into(),
                frame: frame.clone(),
            })
            .unwrap();
        };
        let call = |db: &mut Store, call| {
            db.handle(Packet::Call {
                id: "call".into(),
                call,
            })
            .unwrap()
        };
        let finish = |db: &mut Store, commit| {
            db.handle(Packet::Finish {
                id: "call".into(),
                commit,
            })
        };
        start(&mut db);
        call(&mut db, add("undone"));
        finish(&mut db, false).unwrap();
        assert!(table_rows(&mut db, "app.Access").is_empty());
        start(&mut db);
        let alice = call(&mut db, add("alice"));
        call(
            &mut db,
            Call {
                entity: "app.Holder".into(),
                method: "Patch".into(),
                request: json!({"ref":{"id":alice["id"]},"dateUpdatedForce":true,"name":"Alice"}),
            },
        );
        assert_eq!(
            count_sql(url, r#"SELECT count(*) AS n FROM "pd_app__Access""#),
            0
        );
        let receipt = finish(&mut db, true).unwrap();
        assert_eq!(receipt["writtenSubjects"], json!([alice["id"]]));
        let rs = table_rows(&mut db, "app.Access");
        assert_eq!(rs.len(), 1);
        assert_eq!(rs[0]["kind"], "write");
        assert_eq!(rs[0]["subjects"], json!([alice["id"]]));
        let detail = message_json(f, "payday.AccessDetail", &rs[0]["value"]);
        assert_eq!(detail["address"], "127.0.0.1");
        assert!(detail["request"].is_null());
        let showed = json!({"items":[alice,{"id":STANDARD.encode(other),"alias":"other","tenant":{"id":STANDARD.encode(t)}}]});
        db.handle(Packet::Observe(Observation {
            frame: frame.clone(),
            request: json!({"size":7}),
            input: "app.HolderListRequest".into(),
            output: "app.HolderListResponse".into(),
            answer: Some(showed),
            result: "ok".into(),
            reason: None,
            written: [alice["id"].as_str().unwrap().to_owned()].into(),
        }))
        .unwrap();
        let rs = table_rows(&mut db, "app.Access");
        let read = rs.iter().find(|r| r["kind"] == "read").unwrap();
        assert_eq!(read["subjects"], json!([STANDARD.encode(other)]));
        assert!(message_json(f, "payday.AccessDetail", &read["value"])["request"].is_null());
        let lookup = || Call {
            entity: "app.Holder".into(),
            method: "Get".into(),
            request: json!({"ref":{"id":alice["id"]}}),
        };
        let operator = paydirt::mint(2);
        let ops_tenant = paydirt::mint(1);
        let addr = "shell:person@the-box";
        assert_eq!(
            db.operator_as(lookup(), operator, ops_tenant, addr.into())
                .unwrap()["id"],
            alice["id"]
        );
        let bob = db
            .operator_as(add("bob"), operator, ops_tenant, addr.into())
            .unwrap();
        let named: Vec<_> = table_rows(&mut db, "app.Access")
            .into_iter()
            .filter(|r| r["actorId"] == STANDARD.encode(operator))
            .collect();
        assert_eq!(named.len(), 2);
        for r in named {
            assert_eq!(r["actorTenantId"], STANDARD.encode(ops_tenant));
            assert_eq!(r["tenantId"], STANDARD.encode(t));
            assert_eq!(
                message_json(f, "payday.AccessDetail", &r["value"])["address"],
                addr
            );
            let who = if r["kind"] == "write" { &bob } else { &alice };
            assert_eq!(r["subjects"], json!([who["id"]]));
        }
        start(&mut db);
        call(
            &mut db,
            Call {
                entity: "app.Holder".into(),
                method: "Patch".into(),
                request: json!({"ref":{"id":alice["id"]},"dateUpdatedForce":true,"name":"rolled-back"}),
            },
        );
        let settlement = db
            .handle(Packet::Settle {
                id: "call".into(),
                commit: false,
            })
            .unwrap();
        let fail = Observation {
            frame: frame.clone(),
            request: json!({"ref":{"id":alice["id"]}}),
            input: "app.HolderPatchRequest".into(),
            output: "app.Holder".into(),
            answer: None,
            result: "aborted".into(),
            reason: None,
            written: Default::default(),
        };
        db.handle(Packet::RefusedWrites {
            observation: fail,
            subjects: serde_json::from_value(settlement["refused"].clone()).unwrap(),
            buffered: false,
        })
        .unwrap();
        let aborted: Vec<_> = table_rows(&mut db, "app.Access")
            .into_iter()
            .filter(|r| r["result"] == "aborted")
            .collect();
        assert_eq!(aborted.len(), 1);
        assert_eq!(aborted[0]["kind"], "write");
        assert_eq!(aborted[0]["subjects"], json!([alice["id"]]));
        assert_eq!(
            db.call(&Scope::Internal, lookup()).unwrap()["name"],
            "Alice"
        );
        write(&mut db, &t, "app.Holder", "Erase", json!({"id":bob["id"]}));
        assert!(
            table_rows(&mut db, "app.Access")
                .iter()
                .any(|r| r["action"] == "/app.HolderService/Erase"
                    && r["subjects"] == json!([bob["id"]]))
        );
        raw(r#"ALTER TABLE "pd_app__Access" RENAME TO unavailable_access"#);
        assert_eq!(
            db.operator_as(lookup(), operator, ops_tenant, addr.into())
                .unwrap_err()
                .code,
            "unavailable"
        );
        start(&mut db);
        call(&mut db, add("must-rollback"));
        assert!(finish(&mut db, true).is_err());
        raw(r#"ALTER TABLE unavailable_access RENAME TO "pd_app__Access""#);
        assert!(
            table_rows(&mut db, "app.Holder")
                .iter()
                .all(|r| r["alias"] != "must-rollback")
        );
    });
}

#[test]
fn declared_content_and_secrets_are_preserved_for_their_intended_readers() {
    use paydirt_store::audit_content::Options;
    backends(|f, url, _| {
        for invalid in [
            json!({"default":"values"}),
            json!({"by":{"robot":"values"}}),
        ] {
            assert!(serde_json::from_value::<Options>(invalid).is_err());
        }
        let bad = serde_json::from_value::<Options>(json!({"by":{"robot":"values"}}))
            .err()
            .unwrap()
            .to_string();
        assert!(bad.contains("by.robot") && bad.contains("values"));
        let invalid = f.open(url, &f.policies, false).with_trail(
            serde_json::from_value(json!({"by":{"spaceship":"value"}})).unwrap(),
            &f.descriptors,
            &f.schema,
        );
        assert!(invalid.err().unwrap().message.contains("spaceship"));
        let printed = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
        let copy = printed.clone();
        let mut db = access_store(f, url)
            .with_write_observer(move |change| {
                if change.entity == "app.Robot" {
                    copy.lock().unwrap().push(change.value.cloned());
                }
                Ok(())
            })
            .unwrap();
        let t = provision(&mut db);
        let get_audit = |db: &mut Store, who: &Value, act: &str| {
            table_rows(db, "app.Audit")
                .into_iter()
                .find(|r| r["objectId"] == *who && r["action"].as_str().unwrap().ends_with(act))
                .unwrap()
        };
        let add = |db: &mut Store, kind: &str, req: Value| write(db, &t, kind, "Add", req);
        let holder = add(
            &mut db,
            "app.Holder",
            json!({"tenant":{"id":STANDARD.encode(t)},"alias":"admin"}),
        );
        write(
            &mut db,
            &t,
            "app.Holder",
            "Patch",
            json!({"ref":{"id":holder["id"]},"dateUpdatedForce":true,"name":"Kim Somebody"}),
        );
        let patch = get_audit(&mut db, &holder["id"], "/Patch");
        assert_eq!(patch["fields"], json!([5]));
        for part in ["value", "patch"] {
            let bytes = STANDARD.decode(patch[part].as_str().unwrap()).unwrap();
            assert!(!String::from_utf8_lossy(&bytes).contains("Kim Somebody"));
        }
        let first = get_audit(&mut db, &holder["id"], "/Add");
        assert!(
            !String::from_utf8_lossy(&STANDARD.decode(first["patch"].as_str().unwrap()).unwrap())
                .contains("admin")
        );
        for name in ["alias", "desc", "labels", "name"] {
            assert_eq!(f.policies["app.Tenant"]["fields"][name]["personal"], false);
        }
        write(
            &mut db,
            &t,
            "app.Tenant",
            "Patch",
            json!({"ref":{"id":STANDARD.encode(t)},"dateUpdatedForce":true,"name":"Acme Labs"}),
        );
        let patch = get_audit(&mut db, &json!(STANDARD.encode(t)), "/Patch");
        assert_eq!(patch["fields"], json!([5]));
        for part in ["value", "patch"] {
            assert!(
                String::from_utf8_lossy(&STANDARD.decode(patch[part].as_str().unwrap()).unwrap())
                    .contains("Acme Labs")
            );
        }
        let secret = STANDARD.encode(b"secret-that-must-survive-the-insert");
        let robot = add(
            &mut db,
            "app.Robot",
            json!({"tenant":{"id":STANDARD.encode(t)},"alias":"arm-01","secret":secret}),
        );
        assert!(robot.get("secret").is_none());
        assert_eq!(
            printed.lock().unwrap()[0].as_ref().unwrap()["secret"],
            secret
        );
        let assign = |field: Value, value: Value| json!({"targets":{"selectors":[{"key":{"field":field}}]},"assign":{"value":value}});
        write(
            &mut db,
            &t,
            "app.Robot",
            "Apply",
            json!({"ref":{"id":robot["id"]},"patch":{"messageType":"app.Robot","delta":{"entries":[assign(json!({"name":"keeper"}),json!({"s":"personal-keeper"})),assign(json!({"jsonName":"secret"}),json!({"x":secret})),assign(json!({"name":"alias"}),json!({"s":"arm-02"}))]}}}),
        );
        let patch = get_audit(&mut db, &robot["id"], "/Apply");
        assert_eq!(patch["fields"], json!([4, 8, 32]));
        for part in ["value", "patch"] {
            let bytes = STANDARD.decode(patch[part].as_str().unwrap()).unwrap();
            let s = String::from_utf8_lossy(&bytes);
            assert!(s.contains("arm-02"));
            assert!(!s.contains("personal-keeper"));
            assert!(!s.contains("secret-that-must-survive"));
        }
        let snapshot = message_json(f, "app.Robot", &patch["value"]);
        assert_eq!(snapshot["alias"], "arm-02");
        let seal = add(
            &mut db,
            "app.Seal",
            json!({"alias":"seal-01","secret":secret,"code":"884-113"}),
        );
        assert!(seal.get("secret").is_none() && seal.get("code").is_none());
        let public = write(
            &mut db,
            &t,
            "app.Seal",
            "Get",
            json!({"ref":{"id":seal["id"]},"select":{"all":true,"code":true,"secret":true}}),
        );
        assert!(public.get("secret").is_none() && public.get("code").is_none());
        assert_eq!(public["alias"], "seal-01");
        let literal = if url.starts_with("postgres") {
            format!(
                "decode('{}','hex')",
                hex::encode(b"secret-that-must-survive-the-insert")
            )
        } else {
            format!("X'{}'", hex::encode(b"secret-that-must-survive-the-insert"))
        };
        let robot_secret =
            format!(r#"SELECT count(*) AS n FROM "pd_app__Robot" WHERE f8={literal}"#);
        assert_eq!(count_sql(url, &robot_secret), 1);
        assert_eq!(
            count_sql(
                url,
                &format!(
                    r#"SELECT count(*) AS n FROM "pd_app__Seal" WHERE f8={literal} AND f9='884-113'"#
                )
            ),
            1
        );
    });
}

#[test]
fn represented_and_direct_frames_preserve_sql_null_and_guard_reentry() {
    backends(|f, url, _| {
        let mut db = access_store(f, url);
        let t = provision(&mut db);
        let actor = paydirt::mint(2);
        let caller = paydirt::mint(2);
        for represented in [true, false] {
            let mut frame: Frame = serde_json::from_value(
                json!({"actor":actor,"tenant":t,"action":"/app.RobotService/Add"}),
            )
            .unwrap();
            if represented {
                frame.caller = Some(caller.to_vec());
                frame.caller_tenant = Some(t.to_vec());
                frame.presence = Some("session-a".into());
            }
            db.handle(Packet::Begin {
                id: "r".into(),
                frame: frame.clone(),
            })
            .unwrap();
            let row=db.handle(Packet::Call{id:"r".into(),call:Call{entity:"app.Robot".into(),method:"Add".into(),request:json!({"tenant":{"id":STANDARD.encode(t)},"alias":if represented{"represented"}else{"direct"}})}}).unwrap();
            db.handle(Packet::Finish {
                id: "r".into(),
                commit: true,
            })
            .unwrap();
            let items: Vec<_> = table_rows(&mut db, "app.Audit")
                .into_iter()
                .filter(|v| v["objectId"] == row["id"])
                .collect();
            assert_eq!(items.len(), 1);
            let r = &items[0];
            assert_eq!(r["actorId"], STANDARD.encode(actor));
            if represented {
                assert_eq!(r["callerId"], STANDARD.encode(caller));
                assert_eq!(r["callerTenantId"], STANDARD.encode(t));
                assert_eq!(r["presence"], "session-a");
            } else {
                for k in ["callerId", "callerTenantId", "presence"] {
                    assert!(r[k].is_null());
                }
                let model: paydirt_model::Model = serde_json::from_str(&f.model).unwrap();
                let entity = model.entity("app.Audit").unwrap();
                let nulls = ["caller_id", "caller_tenant_id", "presence"]
                    .map(|name| format!("{} IS NULL", entity.field(name).unwrap().column()))
                    .join(" AND ");
                let tag = hex::encode(id(&r["id"]));
                let value = if url.starts_with("postgres") {
                    format!("decode('{tag}','hex')")
                } else {
                    format!("X'{tag}'")
                };
                assert_eq!(
                    count_sql(
                        url,
                        &format!(
                            r#"SELECT count(*) AS n FROM "pd_app__Audit" WHERE f1={value} AND {nulls}"#
                        )
                    ),
                    1
                );
            }
            frame.action = "/outer.Service/Permitted".into();
            db.handle(Packet::Begin {
                id: "inside".into(),
                frame,
            })
            .unwrap();
            let err = db
                .handle(Packet::Call {
                    id: "inside".into(),
                    call: Call {
                        entity: "app.Robot".into(),
                        method: "Move".into(),
                        request: json!({}),
                    },
                })
                .unwrap_err();
            assert_eq!(err.code == "permission_denied", represented);
            db.handle(Packet::Finish {
                id: "inside".into(),
                commit: false,
            })
            .unwrap();
        }
    });
}

use diesel::connection::{Instrumentation, InstrumentationEvent};
thread_local! {static STATEMENTS:std::cell::RefCell<Option<Vec<String>>>=const { std::cell::RefCell::new(None) };}
fn log() -> Option<Box<dyn Instrumentation>> {
    Some(Box::new(|event: InstrumentationEvent<'_>| {
        if let InstrumentationEvent::StartQuery { query, .. } = event {
            STATEMENTS.with_borrow_mut(|slot| {
                if let Some(lines) = slot {
                    lines.push(query.to_string());
                }
            });
        }
    }))
}
fn enable_sql_trace() {
    diesel::connection::set_default_instrumentation(log).unwrap();
}

#[test]
fn audit_snapshots_use_the_rows_returned_by_insert_and_update() {
    enable_sql_trace();
    backends(|f, url, _| {
        let mut db = access_store(f, url);
        let t = provision(&mut db);
        let robot = write(
            &mut db,
            &t,
            "app.Robot",
            "Add",
            json!({"tenant":{"id":STANDARD.encode(t)},"alias":"robot"}),
        );
        STATEMENTS.with_borrow_mut(|v| *v = Some(vec![]));
        let reading = write(
            &mut db,
            &t,
            "app.Reading",
            "Add",
            json!({"robot":{"id":robot["id"]},"celsius":14.5}),
        );
        let sql = STATEMENTS.with_borrow_mut(|v| v.take().unwrap());
        let selects = |lines: &[String], table: &str| {
            lines
                .iter()
                .filter(|q| {
                    q.starts_with("SELECT ")
                        && q.contains(&format!("FROM \"pd_app__{table}\" AS r"))
                })
                .count()
        };
        assert_eq!(selects(&sql, "Reading"), 0);
        assert!(
            sql.iter()
                .any(|q| q.starts_with("INSERT INTO \"pd_app__Reading\"")
                    && q.contains(" RETURNING "))
        );
        let line = table_rows(&mut db, "app.Audit")
            .into_iter()
            .find(|r| r["objectId"] == reading["id"])
            .unwrap();
        let image = message_json(f, "app.Reading", &line["value"]);
        assert_eq!(image["id"], reading["id"]);
        assert_eq!(image["celsius"], reading["celsius"]);
        assert_eq!(image["robot"], reading["robot"]);
        STATEMENTS.with_borrow_mut(|v| *v = Some(vec![]));
        let changed = write(
            &mut db,
            &t,
            "app.Robot",
            "Patch",
            json!({"ref":{"id":robot["id"]},"dateUpdatedForce":true,"alias":"changed"}),
        );
        let sql = STATEMENTS.with_borrow_mut(|v| v.take().unwrap());
        assert_eq!(selects(&sql, "Robot"), 1);
        let line = table_rows(&mut db, "app.Audit")
            .into_iter()
            .find(|r| r["objectId"] == robot["id"] && r["action"] == "/app.RobotService/Patch")
            .unwrap();
        let image = message_json(f, "app.Robot", &line["value"]);
        assert_eq!(image["alias"], changed["alias"]);
        assert_eq!(image["id"], changed["id"]);
    });
}

#[test]
fn bulk_requests_validate_before_core_and_write_every_named_stamped_item_once() {
    use std::sync::{
        Arc,
        atomic::{AtomicUsize, Ordering},
    };
    enable_sql_trace();
    backends(|f, url, _| {
        let names = Arc::new(AtomicUsize::new(0));
        let out = names.clone();
        let mut db =
            access_store(f, url).with_namer(move |r: paydirt_store::naming::NameRequest<'_>| {
                if r.given.is_empty() {
                    let n = out.fetch_add(1, Ordering::SeqCst) + 1;
                    Ok(if n == 1 {
                        "taken".into()
                    } else {
                        format!("free-{n}")
                    })
                } else {
                    paydirt_store::naming::names(r)
                }
            });
        let a = provision(&mut db);
        let other = paydirt::mint(1);
        db.seed(vec![(
            "app.Tenant".into(),
            json!({"id":STANDARD.encode(other),"alias":"other"}),
        )])
        .unwrap();
        let actor = paydirt::mint(2);
        let begin = |db: &mut Store, call: Call| {
            let frame=serde_json::from_value(json!({"tenant":a,"actor":actor,"trace":[],"action":format!("/{}Service/{}",call.entity,call.method)})).unwrap();
            db.handle(Packet::BeginOrigin {
                id: "bulk".into(),
                frame,
                origin: call,
            })
        };
        let exec = |db: &mut Store, call: Call| {
            begin(db, call.clone())?;
            let done = db.handle(Packet::Call {
                id: "bulk".into(),
                call,
            });
            db.handle(Packet::Finish {
                id: "bulk".into(),
                commit: done.is_ok(),
            })?;
            done
        };
        let call = |kind: &str, method: &str, v: Value| Call {
            entity: kind.into(),
            method: method.into(),
            request: v,
        };
        let robot = |alias: &str| json!({"tenant":{"id":STANDARD.encode(a)},"alias":alias});
        let robots = |items: Vec<Value>| call("app.Robot", "AddMany", json!({"items":items}));
        let alien = json!({"tenant":{"id":STANDARD.encode(other)},"alias":"alien"});
        let err = begin(&mut db, robots(vec![robot("ok"), robot("ok-2"), alien])).unwrap_err();
        assert_eq!(err.code, "not_found");
        assert!(err.message.starts_with("items[2]:"));
        let stamp = "2023-11-14T22:13:20Z";
        let mut forged = robot("forged");
        forged["dateAttested"] = json!(stamp);
        let err = begin(&mut db, robots(vec![robot("safe"), forged])).unwrap_err();
        assert_eq!(err.code, "invalid_argument");
        assert_eq!(err.violations[0].field, "items[1].date_attested");
        assert!(table_rows(&mut db, "app.Robot").is_empty());
        for (kind, field) in [("app.Robot", "dateAttested"), ("app.Holder", "directory")] {
            let original = call(
                kind,
                "Add",
                json!({"tenant":{"id":STANDARD.encode(a)},"alias":"stamped"}),
            );
            let mut stamped = original.clone();
            stamped.request[field] = json!(if kind == "app.Robot" {
                stamp
            } else {
                "server-issued"
            });
            assert!(begin(&mut db, stamped.clone()).is_err());
            begin(&mut db, original).unwrap();
            let row = db
                .handle(Packet::Call {
                    id: "bulk".into(),
                    call: stamped,
                })
                .unwrap();
            if field == "directory" {
                assert_eq!(row[field], "server-issued");
            } else {
                assert!(
                    row[field]
                        .as_str()
                        .unwrap()
                        .starts_with("2023-11-14T22:13:20")
                );
            }
            db.handle(Packet::Finish {
                id: "bulk".into(),
                commit: true,
            })
            .unwrap();
        }
        exec(&mut db, robots(vec![robot("taken")])).unwrap();
        let secret = STANDARD.encode(b"bulk secret");
        let mut named = robot("GIVEN");
        named["secret"] = json!(secret);
        let mut empty = robot("");
        empty["secret"] = json!(secret);
        let batch = robots(vec![empty.clone(), named, empty]);
        begin(&mut db, batch.clone()).unwrap();
        let mut enriched = batch;
        for v in enriched.request["items"].as_array_mut().unwrap() {
            v["dateAttested"] = json!(stamp);
        }
        let added = db
            .handle(Packet::Call {
                id: "bulk".into(),
                call: enriched,
            })
            .unwrap();
        db.handle(Packet::Finish {
            id: "bulk".into(),
            commit: true,
        })
        .unwrap();
        let rows = added["items"].as_array().unwrap();
        assert_eq!(names.load(Ordering::SeqCst), 4);
        assert_eq!(
            rows.iter()
                .map(|r| r["alias"].as_str().unwrap())
                .collect::<Vec<_>>(),
            ["free-3", "given", "free-4"]
        );
        for row in rows {
            assert!(row["secret"].is_null());
            assert!(
                row["dateAttested"]
                    .as_str()
                    .unwrap()
                    .starts_with("2023-11-14T22:13:20")
            );
            let audit = table_rows(&mut db, "app.Audit")
                .into_iter()
                .filter(|r| r["objectId"] == row["id"])
                .collect::<Vec<_>>();
            assert_eq!(audit.len(), 1);
            assert_eq!(audit[0]["actorId"], STANDARD.encode(actor));
            assert_eq!(audit[0]["tenantId"], STANDARD.encode(a));
            assert_eq!(audit[0]["action"], "/app.RobotService/AddMany");
            assert!(
                !String::from_utf8_lossy(
                    &STANDARD
                        .decode(audit[0]["value"].as_str().unwrap())
                        .unwrap()
                )
                .contains("bulk secret")
            );
        }
        let value = if url.starts_with("postgres") {
            "decode('62756c6b20736563726574','hex')"
        } else {
            "X'62756c6b20736563726574'"
        };
        assert_eq!(
            count_sql(
                url,
                &format!(r#"SELECT count(*) AS n FROM "pd_app__Robot" WHERE f8={value}"#)
            ),
            3
        );
        let err = exec(
            &mut db,
            robots(vec![robot("valid"), robot("can't name this!")]),
        )
        .unwrap_err();
        assert_eq!(err.violations[0].field, "items[1].alias");
        for distinct in [false, true] {
            let mut readings = vec![];
            for i in 0..10 {
                let key = if distinct {
                    exec(
                        &mut db,
                        call("app.Robot", "Add", robot(&format!("sensor-{i}"))),
                    )
                    .unwrap()["id"]
                        .clone()
                } else {
                    rows[0]["id"].clone()
                };
                readings.push(json!({"robot":{"id":key},"celsius":i as f64}));
            }
            STATEMENTS.with_borrow_mut(|s| *s = Some(vec![]));
            let saved = exec(
                &mut db,
                call("app.Reading", "AddMany", json!({"items":readings})),
            )
            .unwrap();
            let sql = STATEMENTS.with_borrow_mut(|s| s.take().unwrap());
            assert_eq!(saved["items"].as_array().unwrap().len(), 10);
            assert!(
                saved["items"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .all(|i| i["tenantId"] == STANDARD.encode(a))
            );
            assert_eq!(
                sql.iter()
                    .filter(|q| q.starts_with("INSERT INTO \"pd_app__Reading\""))
                    .count(),
                1
            );
            assert_eq!(
                sql.iter()
                    .filter(
                        |q| q.starts_with("SELECT ") && q.contains("FROM \"pd_app__Robot\" AS r")
                    )
                    .count(),
                if distinct { 10 } else { 1 }
            );
        }
        let count = Arc::new(AtomicUsize::new(0));
        let seen = count.clone();
        let mut db =
            access_store(f, url).with_namer(move |r: paydirt_store::naming::NameRequest<'_>| {
                seen.fetch_add(1, Ordering::SeqCst);
                Ok(if r.given.is_empty() { "taken" } else { r.given }.into())
            });
        assert_eq!(
            exec(&mut db, robots(vec![robot("a-new-one"), robot("taken")]))
                .unwrap_err()
                .code,
            "already_exists"
        );
        assert_eq!(count.swap(0, Ordering::SeqCst), 2);
        assert_eq!(
            exec(&mut db, robots(vec![robot("")])).unwrap_err().code,
            "already_exists"
        );
        assert_eq!(count.load(Ordering::SeqCst), 3);
        assert!(
            !table_rows(&mut db, "app.Robot")
                .iter()
                .any(|r| r["alias"] == "a-new-one")
        );
    });
}

